  "cloudBackup.title": "Sao lưu lên cloud",
  "cloudBackup.intro": "Tune sao lưu các tùy chỉnh của bạn lên Mozaiklabs, được mã hóa ngay trên máy chủ này bằng một khóa mà Mozaiklabs không biết: cài đặt, vùng phát, hồ sơ và tùy chọn, bộ EQ, yêu thích, danh sách phát và radio. Không bao giờ sao lưu thư viện của bạn, cũng như mật khẩu và token của các dịch vụ, với một ngoại lệ: token Discogs, được mã hóa cùng phần còn lại. Mỗi máy giữ tối đa ba bản chụp và mỗi tài khoản tối đa năm máy; các bản cũ nhất sẽ bị xóa.",
